	function project(t, r = 1) {
		const R = Math.min(width * .34, 215) * r;
		const xx = Math.cos(t + angle) * R, yy = Math.sin(t + angle) * (width < 480 ? height * .37 * r : R);
		const z = yy * Math.sin(tilt), scale = 950 / (950 + z);
		return {
			x: width / 2 + xx * scale,
			y: height * .49 + yy * Math.cos(tilt) * scale,
			z,
			scale
		};
	}
	function theta(i) {
		return (-65 + i * 310 / 11) * Math.PI / 180;
	}
	function schedule() {
		if (!raf) raf = requestAnimationFrame(() => {
			raf = 0;
			draw();
		});
	}
	function draw() {
		if (reading) return;
		const rect = $("scene").getBoundingClientRect();
		width = rect.width;
		height = rect.height;
		if (!width) return;
		const dpr = Math.min(devicePixelRatio || 1, 2);
		if (canvas.width !== Math.round(width * dpr) || canvas.height !== Math.round(height * dpr)) {
			canvas.width = Math.round(width * dpr);
			canvas.height = Math.round(height * dpr);
		}
		ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
		ctx.clearRect(0, 0, width, height);
		positions = links.map((_, i) => project(theta(i)));
		edgePositions = [];
		const dark = currentTheme() === "dark";
		const g = ctx.createRadialGradient(width / 2, height * .63, 15, width / 2, height * .63, width * .37);
		g.addColorStop(0, dark ? "rgba(0,0,0,.42)" : "rgba(68,83,54,.065)");
		g.addColorStop(1, dark ? "rgba(0,0,0,0)" : "rgba(68,83,54,0)");
		ctx.fillStyle = g;
		ctx.save();
		ctx.translate(0, height * .33);
		ctx.scale(1, .5);
		ctx.fillRect(0, 0, width, height);
		ctx.restore();
		const gold = token("--gold", "#7a5614"), sage = token("--sage", "#32665f"), mute = token("--line", "#c5c6b8");
		token("--muted", "#454e45");
		for (let i = 0; i < 11; i++) {
			const fading = mode === "cessation" && i <= selected;
			ctx.beginPath();
			for (let j = 0; j <= 24; j++) {
				let p = project(theta(i) + (theta(i + 1) - theta(i)) * (.1 + j / 24 * .8));
				j ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y);
			}
			ctx.strokeStyle = fading ? mute : i === selected ? mode === "arising" ? gold : sage : i < selected ? gold : mute;
			if (selected >= 0) {
				const adjacent = i === selected || i === selected - 1;
				ctx.strokeStyle = adjacent ? mode === "arising" ? gold : sage : mute;
				ctx.lineWidth = adjacent ? 2.8 : 1;
			} else ctx.lineWidth = 1.3;
			ctx.setLineDash(fading ? [3, 5] : []);
			ctx.stroke();
			ctx.setLineDash([]);
			const t = (theta(i) + theta(i + 1)) / 2, p = project(t), q = project(t + .012), rot = Math.atan2(q.y - p.y, q.x - p.x);
			ctx.save();
			ctx.translate(p.x, p.y);
			ctx.rotate(rot);
			ctx.beginPath();
			ctx.moveTo(-5, -3);
			ctx.lineTo(1, 0);
			ctx.lineTo(-5, 3);
			ctx.stroke();
			ctx.restore();
			edgePositions.push({
				x: p.x,
				y: p.y,
				i
			});
		}
		positions.forEach((p, i) => {
			const b = nodeButtons[i];
			b.style.left = p.x + "px";
			b.style.top = p.y + "px";
			b.style.zIndex = String(Math.round(100 - p.z));
			b.querySelector(".orb").style.transform = `scale(${p.scale})`;
		});
	}
	$("arising").onclick = () => setMode("arising");
