	$("scene").addEventListener("pointerdown", (e) => {
		if (reading || e.target.closest("button")) return;
		drag = {
			x: e.clientX,
			y: e.clientY,
			a: angle,
			t: tilt,
			moved: false
		};
		if (e.pointerType === "mouse") $("scene").setPointerCapture(e.pointerId);
	}, { signal: ac.signal });
	$("scene").addEventListener("pointermove", (e) => {
		if (!drag) return;
		const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
		if (Math.abs(dx) + Math.abs(dy) > 6) drag.moved = true;
		if (drag.moved) {
			angle = drag.a + dx * .003;
			tilt = Math.max(.05, Math.min(.85, drag.t + dy * .003));
			schedule();
		}
	}, { signal: ac.signal });
	$("scene").addEventListener("pointerup", (e) => {
		if (!drag) return;
		if (!drag.moved) {
			const r = $("scene").getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;
			const hit = edgePositions.find((p) => Math.hypot(p.x - x, p.y - y) < 24);
			if (hit) showConnection(hit.i);
		}
		drag = null;
	}, { signal: ac.signal });
	$("scene").addEventListener("pointercancel", () => drag = null, { signal: ac.signal });
